templates.template:
.stormWelcome {display:flex;gap:2rem;align-items:center;padding:2rem;margin-bottom:2rem;border-radius:12px;background:fade(@xf-paletteColor2, 14%);}
.stormWelcome h1 {margin:0 0 .5rem;font-size:2rem;}
.stormWelcome .button {margin:.5rem .5rem 0 0;}
.stormArticle {margin-left:20px;}
.stormArticle .block-header {font-size:15px;font-weight:normal;padding:8px 12px 8px 36px;}
.stormArticleContent {position:relative;}
.stormArticleDate {position:absolute;top:8px;left:-21px;width:48px;text-align:center;background:@xf-contentAltBg;border:1px solid @xf-borderColor;border-radius:3px;overflow:hidden;box-shadow:0 1px 3px fade(#000,10%);line-height:1.1;}
.stormArticleDate span {display:block;background:@xf-linkColor;color:@xf-contentBg;font-size:11px;font-weight:bold;text-transform:uppercase;padding:5px 2px;}
.stormArticleDate strong {display:block;font-size:26px;padding:6px 2px;font-weight:normal;font-variant-numeric:tabular-nums;}
.stormArticleByline {display:flex;justify-content:space-between;gap:10px;padding:8px 12px 8px 36px;color:@xf-textColorDimmed;font-size:11px;}
.stormArticleBody {display:flex;gap:20px;padding:4px 12px 14px 36px;align-items:flex-start;}
.stormArticleSnippet {flex:1;min-width:0;line-height:1.5;}
.stormArticleSnippet img {max-width:100%;height:auto;}
.stormArticleBody .avatar {flex-shrink:0;border:4px solid @xf-contentAltBg;box-shadow:0 0 0 1px @xf-borderColor;border-radius:50%;}
.stormArticleContinue {display:block;text-align:right;font-size:12px;font-weight:bold;}
.stormHistoricalRatings {display:flex;flex-wrap:wrap;gap:6px 12px;padding:8px 10px;margin-top:12px;border:1px solid @xf-borderColor;border-radius:3px;background:@xf-contentAltBg;font-size:12px;}
.stormHistoricalRatings small {flex-basis:100%;color:@xf-textColorDimmed;}
.stormHistoricalPoll .block-row {display:flex;justify-content:space-between;gap:12px;}
.stormJoinAddress {display:flex;align-items:center;justify-content:space-between;gap:6px;}
.stormJoinAddress strong {font-size:16px;overflow-wrap:anywhere;}
.stormJoinAddress code {font-size:11px;overflow-wrap:anywhere;}
.stormJoinAddress .button {flex-shrink:0;}
.stormJoinEdition {font-size:13px;margin:14px 0 6px;}
.stormJoinEdition:first-child {margin-top:0;}
.stormJoinManual {margin-top:8px;font-size:11px;}
.stormJoinManual summary {cursor:pointer;}
.stormJoinManual .stormJoinAddress {margin-top:8px;}
.stormJoinPort {margin-top:8px;}
.stormJoinLive {margin-top:16px;padding-top:14px;border-top:1px solid @xf-borderColor;}
.stormJoinVersions {display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0;}
.stormJoinVersion > strong,.stormJoinVersion > span {display:block;font-size:12px;}
.stormJoinVersion > span {margin-top:3px;}
.stormJoinPlayers {border-top:1px solid @xf-borderColor;padding-top:12px;}
.stormJoinPlayers h4 {margin:0 0 8px;font-size:13px;}
.stormJoinPlayers ul {display:flex;flex-wrap:wrap;gap:6px;list-style:none;padding:0;margin:0;}
.stormJoinPlayers li {padding:4px 7px;border:1px solid @xf-borderColor;border-radius:4px;background:@xf-contentAltBg;font-size:12px;overflow-wrap:anywhere;max-width:100%;}
.stormJoin .button {font-size:11px;padding:5px 8px;}
.stormJoin p {margin:10px 0;font-size:12px;line-height:1.6;}
.stormJoinBadge {display:inline-block;padding:3px 7px;border-radius:20px;background:@xf-contentHighlightBg;color:@xf-textColor;font-size:11px;font-weight:bold;border:1px solid @xf-borderColor;}
.stormJoinBadge--online {border-color:@xf-linkColor;}
.stormJoin small {display:block;margin-top:6px;font-size:11px;}
.message .reactionsBar {border-radius:3px;font-size:12px;}
.message .reactionSummary {gap:4px;}
.reaction--small img {width:16px;height:16px;}
.reactionSelect {max-width:calc(100vw - 24px);}
.reactionSelect .reactionSelect-reaction {padding:7px;}
@media(max-width:650px) {.reactionSelect {flex-wrap:wrap;} .reactionSelect .reactionSelect-reaction {padding:6px;}}
@media(max-width:450px) {.stormArticleBody .avatar {display:none;} .stormArticleByline {flex-wrap:wrap;}}
@media(max-width:650px) {.stormWelcome {flex-direction:column;text-align:center;padding:1.5rem;} .stormWelcome h1 {font-size:1.6rem;}}
